begin;
drop function if exists public.reserve_wallet_withdrawal(uuid,numeric,text,text,text,text,text,jsonb);
create function public.reserve_wallet_withdrawal(p_user_id uuid,p_amount numeric,p_currency text,p_payment_method text,p_provider text,p_provider_reference text,p_description text,p_metadata jsonb default '{}'::jsonb) returns public.wallet_transactions language plpgsql security definer set search_path=public as $$ declare w public.wallets; tx public.wallet_transactions; b numeric; begin if p_user_id is null or p_amount<=0 then raise exception 'INVALID_WITHDRAWAL'; end if; if auth.uid() is not null and auth.uid()<>p_user_id and not public.is_platform_admin(auth.uid()) then raise exception 'FORBIDDEN'; end if; select * into w from public.wallets where user_id=p_user_id for update; if not found then raise exception 'WALLET_NOT_FOUND'; end if; if w.status<>'active' or not w.withdrawals_enabled then raise exception 'WITHDRAWALS_DISABLED'; end if; if w.currency<>p_currency or w.balance<p_amount then raise exception 'INSUFFICIENT_FUNDS'; end if; b:=w.balance; update public.wallets set balance=balance-p_amount,updated_at=now() where id=w.id; insert into public.wallet_transactions(wallet_id,user_id,type,status,amount,currency,balance_before,balance_after,provider,provider_reference,description,metadata,payment_method,reference) values(w.id,p_user_id,'withdrawal','pending',p_amount,p_currency,b,b-p_amount,p_provider,p_provider_reference,p_description,coalesce(p_metadata,'{}'::jsonb),p_payment_method,p_provider_reference) returning * into tx; return tx; end; $$;
revoke all on function public.reserve_wallet_withdrawal(uuid,numeric,text,text,text,text,text,jsonb) from public,anon;
grant execute on function public.reserve_wallet_withdrawal(uuid,numeric,text,text,text,text,text,jsonb) to authenticated,service_role;
create or replace function public.request_creator_payout(p_amount numeric,p_currency text default 'USD',p_provider text default 'mpesa',p_destination text default null) returns public.creator_payouts language plpgsql security definer set search_path=public as $$ declare tx public.wallet_transactions; p public.creator_payouts; min_amount numeric; ref text; begin if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if; select min_creator_payout into min_amount from public.monetization_settings where id=true; if p_amount<min_amount then raise exception 'MIN_PAYOUT_NOT_MET'; end if; ref:='creator-payout:'||gen_random_uuid()::text; tx:=public.reserve_wallet_withdrawal(auth.uid(),p_amount,p_currency,p_provider,p_provider,ref,'Creator payout',jsonb_build_object('destination',p_destination)); insert into public.creator_payouts(user_id,wallet_transaction_id,amount,currency,provider,destination,status,provider_reference) values(auth.uid(),tx.id,p_amount,p_currency,p_provider,p_destination,'pending',ref) returning * into p; return p; end; $$;
revoke all on function public.request_creator_payout(numeric,text,text,text) from public,anon;
grant execute on function public.request_creator_payout(numeric,text,text,text) to authenticated;
create or replace function public.platform_set_wallet_control(p_user_id uuid,p_status text default null,p_spending_enabled boolean default null,p_withdrawals_enabled boolean default null,p_reason text default null) returns public.wallets language plpgsql security definer set search_path=public as $$ declare w public.wallets; begin if auth.uid() is null or not public.is_platform_admin(auth.uid()) then raise exception 'FORBIDDEN'; end if; if p_status is not null and p_status not in ('active','frozen','closed') then raise exception 'INVALID_STATUS'; end if; update public.wallets set status=coalesce(p_status,status),spending_enabled=coalesce(p_spending_enabled,spending_enabled),withdrawals_enabled=coalesce(p_withdrawals_enabled,withdrawals_enabled),frozen_reason=case when p_status='frozen' then p_reason when p_status='active' then null else frozen_reason end,frozen_at=case when p_status='frozen' then now() when p_status='active' then null else frozen_at end,updated_at=now() where user_id=p_user_id returning * into w; if not found then raise exception 'WALLET_NOT_FOUND'; end if; return w; end; $$;
revoke all on function public.platform_set_wallet_control(uuid,text,boolean,boolean,text) from public,anon,authenticated;
grant execute on function public.platform_set_wallet_control(uuid,text,boolean,boolean,text) to authenticated;
create or replace function public.platform_approve_creator_payout(p_payout_id uuid,p_approve boolean,p_reason text default null) returns public.creator_payouts language plpgsql security definer set search_path=public as $$ declare p public.creator_payouts; begin if auth.uid() is null or not public.is_platform_admin(auth.uid()) then raise exception 'FORBIDDEN'; end if; select * into p from public.creator_payouts where id=p_payout_id for update; if not found or p.status<>'pending' then raise exception 'INVALID_PAYOUT_STATE'; end if; if p_approve then update public.creator_payouts set status='approved',approved_at=now(),approved_by=auth.uid(),metadata=metadata||jsonb_build_object('approval_reason',p_reason) where id=p_payout_id returning * into p; else update public.creator_payouts set status='cancelled',approved_at=now(),approved_by=auth.uid(),metadata=metadata||jsonb_build_object('rejection_reason',p_reason) where id=p_payout_id returning * into p; perform public.fail_wallet_withdrawal(p.wallet_transaction_id,'platform-rejected','rejected',coalesce(p_reason,'Platform rejected payout')); end if; return p; end; $$;
revoke all on function public.platform_approve_creator_payout(uuid,boolean,text) from public,anon,authenticated;
grant execute on function public.platform_approve_creator_payout(uuid,boolean,text) to authenticated;
commit;
